Definition exit_f (c : CC.cutpoint) (ps : SR.post_spec) : bool :=
  let cells := SR.ps_cells ps in
  (CL.ps_at ps [RET] && CL.ps_keeps ps CSAVED && Nat.leb FT.NF (CC.cp_nx c)
   && has cells (KWord (SA e_o 0) 8 (APC.eaddz CAP 1)) && has cells (KWord (SA e_o 8) 8 (APC.eaddz e_size 1)) && has cells (KWord (SA e_o 16) 8 e_p)
   && has cells (KBlob (SA e_p 0) e_size 0) && has cells (KWord (SA (APC.eadd e_size e_p) 0) 1 e_c) && has cells (KWord (SA (APC.eadd e_size e_p) 1) 1 (ELit 0)))%bool.
Definition leaf_f (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S00$i;R+M$c;R+N$k;R+M$ps;R+O$t;R+P-PRN$t;R+P+4#12$j;R+M$s;R'Q,R$pc;R+C!2'W!2'W!1'X!4'Y'@'A!3,B+C'D!1,E+C#1!2'Z#6,[!2'\#5#3").
Lemma leaf_f_ok : CH2.leaves_all F.CPS F.TAGS leaf_f = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,3+4,5!3+6+4!3'L';'>'^0,5").
Qed.

(* [comment removed for export] *)
Definition pre (i : nat) : bool := Nat.eqb i 0.
Definition hd_base (i : nat) : expr := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S20!2+^4+^2+^2!1,U,^6$i;R+M!3'^1+^2+^2!3'^30!4,^5+^2+^211!4'^7'^8#1'H!1,E0").
Definition hd_size (i : nat) : expr := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S20!2+^4+^2+^2!1,U,^6$i;R+M!3'^9+^2+^2!3'^30!4,^5+^2+^211!4'^7'^8#1'H!1,E0").
Definition CAP2 : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|10;!3,^:,^;!3,S,T!1,U!1,2|20;'V!1,U!1,^<0").                      (* [comment removed for export] *)
Definition NEWCAP : expr := EAlu ALU_ADD (EMd M_MUL (ELit 8) (EAlu ALU_SRL CAP2 (ELit 3))) (ELit 8).      (* [comment removed for export] *)
Definition exit_g (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) : bool :=
  let cells := SR.ps_cells ps in let pe := hd_base i in let ce := hd_size i in
  (CL.ps_at ps [RET] && CL.ps_keeps ps CSAVED && CH2.blocks_vars_lt (CC.cp_nx c) (nth i G.BLS []) && Nat.leb GT.NF (CC.cp_nx c)
   && negb (pre i) && match nth i G.BLS [] with [_] => true | _ => false end
   && has cells (KWord (SA e_o 0) 8 (APC.eaddz ce 1)) && has cells (KWord (SA e_o 8) 8 CAP) && has cells (KWord (SA e_o 16) 8 pe)
   && has cells (KBlob (SA pe 0) (APC.eaddz CAP (-1)) 0) && has cells (KWord (SA (APC.eadd CAP pe) (-1)) 1 e_c) && has cells (KWord (SA (APC.eadd CAP pe) 0) 1 (ELit 0))
   && expr_eqb ce NEWCAP && has cells (KDisj (SA pe 0) ce (SA e_p 0) CAP)
   && match pe with EVar v => Nat.leb GT.NF v | _ => false end)%bool.
Definition leaf_g (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S50!1'^A#7!1'^E#8!1'X!1'^E#2!1'^G#2!1'^G#8$i;R+M$c;R+N$k;R+M$ps;R+O$t;R+P-PRN$t;R+P+4#12$j;R+M$s;R'Q,R$pc;R+C-4RN$~R+4+4!4'Y'@'A!3,B+C'D!1,E+C#12-^=RN$x;R!1+^=+M+4!3'^>'K#6#42$j;R+M-^=RN$x;R!1+^=+N+4!3'^?+N'I#12$cj;R+N!2'W!2'W!2'^@'F0!2'^@0!2'^B!1'^A#1'^C-4RN$~R+4+4!2'^D#3'@2!2'W!2'W!2'W!2'W12!2'^F3!2'^H#5}:!2'^I'F3!2'^F3'^J!2'W!2'W!2'W!1'X12!2'^F43!2'^I'F4,R,R!3'^K#6#5#3").
Lemma leaf_g_ok : CH2.leaves_all G.CPS G.TAGS leaf_g = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,3+4,5!3+6+4!3'L'I'J'^L,5").
Qed.

